#include <iostream>
#include <vector>
#include <algorithm>

// Helper function for k-means clustering
void kMeans(const std::vector<Color>& colors, int k, int maxIterations, std::vector<int>& clusterLabels) {
  // Initialize cluster labels
  for (int i = 0; i < k; ++i) {
    clusterLabels.push_back(i);
  }

  // Shuffle the colors to randomize the order
  std::random_shuffle(colors.begin(), colors.end());

  // Iterate through the specified number of iterations
  for (int i = 0; i < maxIterations; ++i) {
    // Step 1: Determine the closest center for each color
    double minDist = std::numeric_limits<double>::max();
    int closestCenter = -1;
    for (int c = 0; c < k; ++c) {
      double dist = 0;
      for (int i = 0; i < colors.size(); ++i) {
        if (colors[i].getClusterLabel() == c) {
          dist += (colors[i].getR() - colors[c].getR()) * (colors[i].getR() - colors[c].getR()) +
                  (colors[i].getG() - colors[c].getG()) * (colors[i].getG() - colors[c].getG()) +
                  (colors[i].getB() - colors[c].getB()) * (colors[i].getB() - colors[c].getB());
        }
      }
      if (minDist > dist) {
        minDist = dist;
        closestCenter = c;
      }
    }

    // Step 2: Update the colors' cluster labels
    for (int i = 0; i < colors.size; ++i) {
      if (colors[i].getClusterLabel() != closestCenter) {
        colors[i].setClusterLabel(closestCenter);
      }

// Step 3: Recalculate the means
int center[3] = {0, 0, 0};
for (int c = 0; c < k; ++c) {
center[c] = (clusterLabels[c] == 0) ? colors[0].getR() : colors[colors[clusterLabels[c] - 1].getClusterLabel()].getR();
}
