    // Your Facebook access token
    public string accessToken = "YOUR_ACCESS_TOKEN";

    // The ID of the video you want to download
    public string videoId = "YOUR_VIDEO_ID";

    // The path to save the video
    public string savePath = "PATH_TO_SAVE_THE_VIDEO";

    void Start()
