class ActorCritic:
    def __init__(self, state_space, action_space, reward_func, discount_func, optimizer):
        self.state_space = state_space
        self.action_space = action_space
        self.reward_func = reward_func
        self.discount_func = discount_func
        self.optimizer = optimizer
        self.actor = self.build_actor()
        self.critic = self.build_critic()

    def build_actor(self):
        def default_actor(state):
            return np.random.choice(self.action_space)

        return np.partial(default_actor, list(self.state_space))

    def build_critic(self):
        def default_critic(state, action):
            return self.reward_func(state) + self.discount_func(state)

        return np.partial(default_critic, list(self.state_space), list(self.action_space))

    def update_model(self, state, action, reward, next_state, done):
        state_flat = np.reshape(state, [-1])
        action_flat = np.reshape(action, [-1])
